/// <summary>
/// Service class for CB197_SalesReturnsClaimswithaSupplier.
/// </summary>
class MetSalesReturnClaimwithsupplierService
{
}

Method.Source:
/// <summary>
/// Process the main logic of the class.
/// </summary>    
public void process()
{
    Query                   query;
    QueryBuildDataSource    qbdSalesTable, qbdSalesLine;

    query = new Query();
    qbdSalesTable = query.addDataSource(tableNum(SalesTable));

    qbdSalesLine = qbdSalesTable.addDataSource(TableNum(SalesLine));
    qbdSalesLine.addLink(FieldNum(SalesTable, SalesId), FieldNum(SalesLine, SalesId));
    qbdSalesLine.joinMode(JoinMode::InnerJoin);

    qbdSalesTable.addRange(fieldNum(SalesTable, ReturnStatus)).value(enum2Str(ReturnStatusHeader::Closed));
    qbdSalesTable.addRange(fieldNum(SalesTable, SalesType)).value(enum2Str(SalesType::ReturnItem));

    QueryRun    queryRun    = new QueryRun(query);

    while (queryRun.next())
    {
        boolean             createInvoice = false;
        SalesTable          salesTable    = queryRun.get(tableNum(SalesTable));
        SalesLine           salesLine     = queryRun.get(tableNum(SalesLine));
        METSalesLine        metSalesLine;
        ReqItemTable        reqItemTable;
        InventDim           inventDim;
        InventSiteId        reqsite, salesSite;
        InventLocationId    reqWarehouse, salesWarehouse;
        VendAccount         vendAccount;

        if (ReturnReasonCode::find(salesTable.ReturnReasonCodeId).METSupplierRelatedClaim && !METSalesLine::find(salesLine.RecId).PendingInvNumber)
        {
            VendPackingSlipJour     vendPackingSlipJour;
            VendInvoiceInfoTable    vendInvoiceInfoTableLoc, vendInvoiceInfoTableExist;
            VendInvoiceInfoLine     vendInvoiceInfoLine;
            VendPackingSlipTrans    vendPackingSlipTrans;
            VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

            salesSite      = salesLine.inventDim().InventSiteId;
            salesWarehouse = salesLine.inventDim().InventLocationId;

            while select reqItemTable 
                where reqItemTable.ItemId == salesLine.ItemId
                join inventDim 
                where inventDim.InventDimId == reqItemTable.CovInventDimId
                    && inventDim.InventSiteId == salesSite
                    && inventDim.InventLocationId == salesWarehouse
                    && reqItemTable.VendId != ''
            {
                if(!vendAccount)
                {
                    vendAccount = reqItemTable.VendId;
                    break;
                }
            }

            if(vendAccount)
            {
                this.createPendingVendorInvoice(vendAccount, salesTable, salesSite, salesWarehouse);
            }
        }
    }
}

/// <summary>
/// Create the pending vendor invoice of the PO.
/// </summary>
/// <param name = "_vendAccount">VendAccount</param>
/// <param name = "_salesTable">SalesTable</param>
/// <param name = "_returnSite">InventSiteId</param>
/// <param name = "_returnWarehous">InventLocationID</param>
/// <returns>VendInvoiceInfoTable</returns>
public VendInvoiceInfoTable createPendingVendorInvoice(VendAccount       _vendAccount, 
                                                        SalesTable       _salesTable,
                                                        InventSiteId     _returnSite,
                                                        InventLocationID _returnWarehous)
{
    VendInvoiceInfoTable    vendInvoiceInfoTable;
    VendInvoiceInfoSubTable vendInvoiceInfoSubTable;
    VendInvoiceInfoLine     vendInvoiceInfoLine;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
    PurchParmUpdate         purchParmUpdate;

    PurchFormletterParmData     purchFormletterParmData = PurchFormletterParmData::newData(DocumentStatus::Invoice, VersioningUpdateType::Initial);
    PurchFormLetter             purchFormLetter;

    ttsbegin;
    select vendInvoiceInfoTable
        where vendInvoiceInfoTable.METSalesId == _salesTable.SalesId
            && vendInvoiceInfoTable.METReturnSite == _returnSite
            && vendInvoiceInfoTable.METReturnWarehous == _returnWarehous;
    if(vendInvoiceInfoTable.RecId)
    {
        this.createPendingVendorInvoiceLines(_salesTable, vendInvoiceInfoTable);
    }
    else
    {
        purchFormletterParmData.init();
        purchFormletterParmData.parmOnlyCreateParmUpdate(true);
        purchFormletterParmData.createData(false);
        purchParmUpdate = purchFormletterParmData.parmParmUpdate();

        vendInvoiceInfoTable.clear();
        vendInvoiceInfoTable.initValue();

        vendInvoiceInfoTable.DocumentOrigin  = DocumentOrigin::Manual;
        vendInvoiceInfoTable.DeliveryName = '';
        vendInvoiceInfoTable.InvoiceAccount = _vendAccount;

        vendInvoiceInfoTable.defaultRow(null, null, true);
        vendInvoiceInfoTable.Num                    = _salesTable.ReturnItemNum;
        vendInvoiceInfoTable.VendInvoiceSaveStatus  = VendInvoiceSaveStatus::Pending;
        vendInvoiceInfoTable.DocumentDate           = systemDateGet();
        vendInvoiceInfoTable.LastMatchVariance      = LastMatchVarianceOptions::OK;
        vendInvoiceInfoTable.CashDiscDate           = _salesTable.Deadline;
        vendInvoiceInfoTable.METReturnSite          = _returnSite;
        vendInvoiceInfoTable.METReturnWarehous      = _returnWarehous;
        vendInvoiceInfoTable.METSalesId             = _salesTable.SalesId;
        vendInvoiceInfoTable.METReturnInvoices      = _salesTable.ReturnItemNum;

        vendInvoiceInfoTable.insert();

        if(vendInvoiceInfoTable)
        {
            vendInvoiceInfoSubTable.clear();
            vendInvoiceInfoSubTable.initValue();
            vendInvoiceInfoSubTable.defaultRow();

            vendInvoiceInfoSubTable.ParmId      = vendInvoiceInfoTable.ParmId;
            vendInvoiceInfoSubTable.OrigPurchId = vendInvoiceInfoTable.PurchId;
            vendInvoiceInfoSubTable.PurchName   = vendInvoiceInfoTable.PurchName;
            vendInvoiceInfoSubTable.TableRefId  = vendInvoiceInfoTable.TableRefId;

            vendInvoiceInfoSubTable.insert();
        }

        this.createPendingVendorInvoiceLines(_salesTable, vendInvoiceInfoTable);
    }
    ttscommit;

    return vendInvoiceInfoTable;
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <param name = "_vendInvoiceInfoTable">VendInvoiceInfoTable</param>
public void createPendingVendorInvoiceLines(SalesTable          _salesTable, 
                                            VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    SalesLine               salesLine;
    VendInvoiceInfoLine     vendInvoiceInfoLine;

    while select salesLine
        where salesLine.SalesId == _salesTable.SalesId
    {
        vendInvoiceInfoLine.clear();

        vendInvoiceInfoLine.initValue();

        vendInvoiceInfoLine.ParmId              = _vendInvoiceInfoTable.ParmId;
        vendInvoiceInfoLine.LineNum             = any2int(salesLine.LineNum);
        vendInvoiceInfoLine.DeliveryName        = _vendInvoiceInfoTable.DeliveryName;
        vendInvoiceInfoLine.TableRefId          = _vendInvoiceInfoTable.TableRefId;
        vendInvoiceInfoLine.currencyCode        = _vendInvoiceInfoTable.CurrencyCode;

        vendInvoiceInfoLine.InvoiceAccount      = _vendInvoiceInfoTable.InvoiceAccount;
        vendInvoiceInfoLine.InventDimId         = salesLine.InventDimId;
        vendInvoiceInfoLine.OrderAccount        = _vendInvoiceInfoTable.OrderAccount;
        vendInvoiceInfoLine.ItemId              = salesLine.ItemId;
        vendInvoiceInfoLine.InventTransId       = salesLine.InventTransId;

        vendInvoiceInfoLine.DocumentOrigin      = DocumentOrigin::Manual;
        vendInvoiceInfoLine.ReceiveNow          = salesLine.SalesQty;

        vendInvoiceInfoLine.PurchUnit           = salesLine.SalesUnit;
        vendInvoiceInfoLine.PurchPrice          = salesLine.SalesPrice;
        vendInvoiceInfoLine.InventNow           = salesLine.SalesQty;
        vendInvoiceInfoLine.LineAmount          = salesLine.LineAmount;
        vendInvoiceInfoLine.DefaultDimension    = salesLine.DefaultDimension;
        vendInvoiceInfoLine.ProcurementCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(salesLine.ItemId, EcoResCategoryNamedHierarchyRole::Procurement).Category;

        //Insert pending invoice lines.
        vendInvoiceInfoLine.insert();

        //Insert pending invoice sub-lines.
        this.createPendingVendorInvoiceInfoSubLines(salesLine.InventTransId, vendInvoiceInfoLine);
        this.updatePendingInvRef(salesLine, _vendInvoiceInfoTable);
    }
}

/// <summary>
/// Create the pending vendor invoice lines of the PO.
/// </summary>
/// <param name = "_inventTransId">InventTransId</param>
/// <param name = "_vendInvoiceInfoLine">VendInvoiceInfoLine</param>
public void createPendingVendorInvoiceInfoSubLines(InventTransId _inventTransId, VendInvoiceInfoLine _vendInvoiceInfoLine)
{
    VendPackingSlipTrans    vendPackingSlipTrans;
    VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

    vendInvoiceInfoSubLine.clear();

    //Insert the sub line details from the table <c>VendPackingSlipTrans</c>
    while select InventTransId, PackingSlipId, Qty, RecId, TableId from vendPackingSlipTrans
        where vendPackingSlipTrans.InventTransId == _inventTransId
    {
        vendInvoiceInfoSubLine.initValue();
        vendInvoiceInfoSubLine.defaultRow();

        vendInvoiceInfoSubLine.ParmId               = _vendInvoiceInfoLine.ParmId;
        vendInvoiceInfoSubLine.InventNow            = vendPackingSlipTrans.Qty;
        vendInvoiceInfoSubLine.ReceiveNow           = vendPackingSlipTrans.Qty;
        vendInvoiceInfoSubLine.DocumentId           = vendPackingSlipTrans.PackingSlipId;
        vendInvoiceInfoSubLine.LineRefRecId         = _vendInvoiceInfoLine.RecId;
        vendInvoiceInfoSubLine.JournalRefRecId      = vendPackingSlipTrans.RecId;
        vendInvoiceInfoSubLine.JournalRefTableId    = vendPackingSlipTrans.TableId;

        vendInvoiceInfoSubLine.insert();
    }
}

/// <summary>
/// Update invoice number.
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_vendInvInfoTable">VendInvoiceInfoTable</param>
public void updatePendingInvRef(SalesLine _salesLine, VendInvoiceInfoTable _vendInvInfoTable)
{
    METSalesLine    metSalesLine;

    select forupdate metSalesLine 
        where metSalesLine.SalesLine == _salesLine.RecId;
    if(metSalesLine.RecId)
    {
        metSalesLine.PendingInvNumber = _vendInvInfoTable.Num;
        metSalesLine.doUpdate();
    }
}
